class UnionFindBasic {
  constructor(n) {
    this.parent = Array.from({length:n},(_,i)=>i);
    this.components = n;
  }
  find(x) {
    while (this.parent[x] !== x) x = this.parent[x];
    return x;
  }
  union(x, y) {
    const rx = this.find(x), ry = this.find(y);
    if (rx === ry) return false;
    this.parent[rx] = ry;
    this.components--;
    return true;
  }
  connected(x, y) { return this.find(x) === this.find(y); }
}

