function kruskalMSTImpl(n, edges) {
  edges.sort((a,b) => a[0]-b[0]);
  const uf = new UnionFind(n);
  let mstWeight = 0, edgesUsed = 0;
  for (const [w, u, v] of edges) {
    if (uf.union(u, v)) {
      mstWeight += w;
      edgesUsed++;
      if (edgesUsed === n-1) break;
    }
  }
  return {mstWeight, connected: edgesUsed === n-1};
}

function minCostConnectPointsImpl(points) {
  const n = points.length, allEdges = [];
  for (let i = 0; i < n; i++)
    for (let j = i+1; j < n; j++) {
      const d = Math.abs(points[i][0]-points[j][0]) + Math.abs(points[i][1]-points[j][1]);
      allEdges.push([d, i, j]);
    }
  allEdges.sort((a,b) => a[0]-b[0]);
  const uf = new UnionFind(n);
  let total = 0, used = 0;
  for (const [d, i, j] of allEdges) {
    if (uf.union(i, j)) { total += d; used++; if (used === n-1) break; }
  }
  return total;
}

