const MODULE8_PROBLEMS = [
  {id:684,  pattern:'UF cycle detect',    nc150:true},
  {id:323,  pattern:'UF component count', nc150:true},
  {id:200,  pattern:'DFS flood fill',     nc150:true},
  {id:547,  pattern:'UF or DFS',          nc150:true},
  {id:721,  pattern:'UF email grouping',  nc150:true},
  {id:1584, pattern:'Kruskal MST',        nc150:true},
  {id:1061, pattern:'UF equivalence',     nc150:false},
  {id:990,  pattern:'UF equation',        nc150:true}
];

function classifyUnionFindProblem(signals) {
  const map = {
    'cycle': 'UF cycle detect',
    'components': 'UF component count',
    'dfs': 'DFS flood fill',
    'mst': 'Kruskal MST',
    'merge': 'UF email grouping',
    'equivalence': 'UF equivalence',
    'dynamic': 'UF component count'
  };
  for (const s of signals) if (map[s]) return map[s];
  return 'unknown';
}

function module8Summary() {
  const vals = MODULE8_PROBLEMS;
  return {
    total: vals.length,
    nc150: vals.filter(p=>p.nc150).length,
    unionFind: vals.filter(p=>p.pattern.startsWith('UF')||p.pattern.startsWith('Kruskal')).length,
    dfs: vals.filter(p=>p.pattern.startsWith('DFS')).length
  };
}

function mstAlgorithmFor(density) {
  return density === 'sparse' ? 'Kruskal' : 'Prim';
}
